changeSet.sql:
ALTER TABLE lbi_area_campo ADD COLUMN etichetta VARCHAR(255) NULL;

ALTER TABLE lbi_area_campo DROP CONSTRAINT ck_area_campo_con_effetto;
ALTER TABLE lbi_area_campo ADD CONSTRAINT ck_area_campo_con_effetto
    CHECK (escluso OR nome_campo IS NOT NULL OR etichetta IS NOT NULL);

ALTER TABLE lbi_area_campo ADD CONSTRAINT ck_area_campo_etichetta_non_vuota
    CHECK (etichetta IS NULL OR length(btrim(etichetta)) > 0);
ALTER TABLE lbi_area_campo ADD CONSTRAINT ck_area_campo_escluso_etichetta
    CHECK (NOT (escluso AND etichetta IS NOT NULL));
